        System.out.println();
        System.out.println("Looking for: 'R$ 779,80'");
        System.out.println("Contains check: " + financeEmail.getBody().contains("R$ 779,80"));
        System.out.println();
        System.out.println("Body bytes:");
        for (char c : financeEmail.getBody().toCharArray()) {
            System.out.print((int)c + " ");
        }
        System.out.println();
        System.out.println();
        System.out.println("Search string bytes:");
        for (char c : "R$ 779,80".toCharArray()) {
            System.out.print((int)c + " ");
        }
    }
}

